using System.ComponentModel.DataAnnotations;
using backend.Models;

namespace backend.DTOs;

public sealed record Schedule(
  string Id,
  ArtistSummary Artist,
  string ActivityTitle,
  string? ActivityDescription,
  DateTimeOffset StartTime,
  DateTimeOffset EstimatedEndTime,
  string Location,
  string Category,
  string Status,
  bool IsPublic,
  string? ConcertId,
  string? ConcertName,
  IReadOnlyList<StaffSummary> Staff,
  DateTimeOffset CreatedAt,
  DateTimeOffset UpdatedAt,
  string? CreatedBy,
  string? UpdatedBy,
  uint Version);

// The schedule Id is generated by the server.
public record ScheduleInput : IValidatableObject
{
  public required int ArtistId { get; init; }

  [Required, MaxLength(100)]
  public required string ActivityTitle { get; init; }

  [MaxLength(2500)]
  public string? ActivityDescription { get; init; }

  public required DateTimeOffset StartTime { get; init; }

  public required DateTimeOffset EstimatedEndTime { get; init; }

  [Required, MaxLength(200)]
  public required string Location { get; init; }

  [Required]
  [AllowedValues(
    ScheduleCategories.Concert,
    ScheduleCategories.Recording,
    ScheduleCategories.Rehearsal,
    ScheduleCategories.Interview,
    ScheduleCategories.Event,
    ScheduleCategories.Off,
    ScheduleCategories.Other)]
  public string Category { get; init; } = ScheduleCategories.Other;

  [Required]
  [AllowedValues(
    ScheduleStatuses.Planned,
    ScheduleStatuses.Confirmed,
    ScheduleStatuses.Cancelled)]
  public string Status { get; init; } = ScheduleStatuses.Planned;

  public bool IsPublic { get; init; }

  [MaxLength(50)]
  public string? ConcertId { get; init; }

  public IReadOnlyList<string> StaffIds { get; init; } = [];

  public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
  {
    if (StartTime >= EstimatedEndTime)
    {
      yield return new ValidationResult(
        "EstimatedEndTime must be after StartTime.",
        [nameof(EstimatedEndTime)]);
    }
  }
}

public sealed record UpdateSchedule : ScheduleInput
{
  // Send back the Version you received; a mismatch means someone else edited it.
  public required uint Version { get; init; }
}

// Calendar query: GET /schedule?from=...&to=...&artistId=...
public sealed record ScheduleQuery : IValidatableObject
{
  public required DateTimeOffset From { get; init; }

  public required DateTimeOffset To { get; init; }

  public int? ArtistId { get; init; }

  public string? Category { get; init; }

  public string? Status { get; init; }

  public string? ConcertId { get; init; }

  public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
  {
    if (From >= To)
    {
      yield return new ValidationResult(
        "To must be after From.",
        [nameof(To)]);
    }
  }
}
